using System.Globalization;

namespace MagDeer.Core;

/// <summary>Embedded UI texts: English, Czech, Polish, German and Spanish. No network translation.</summary>
public static class L
{
    public sealed record LanguageChoice(string Id, string Label, string CultureName)
    {
        public override string ToString() => Label;
    }
    public static IReadOnlyList<LanguageChoice> Languages { get; } = new[]
    {
        new LanguageChoice("en", "English · EN", "en-GB"), new LanguageChoice("cs", "Čeština · CZ", "cs-CZ"),
        new LanguageChoice("pl", "Polski · PL", "pl-PL"), new LanguageChoice("de", "Deutsch · DE", "de-DE"),
        new LanguageChoice("es", "Español · ES", "es-ES")
    };
    public static string Language { get; private set; } = "en";
    private static int languageIndex;
    private static CultureInfo culture = CultureInfo.GetCultureInfo("en-GB");
    public static CultureInfo Culture => culture;
    public static void SetLanguage(string language)
    {
        languageIndex = 0;
        for (int i = 0; i < Languages.Count; i++) if (Languages[i].Id == language) { languageIndex = i; break; }
        Language = Languages[languageIndex].Id;
        culture = CultureInfo.GetCultureInfo(Languages[languageIndex].CultureName);
    }
    public static string Text(string key, params object[] args)
    {
        if (!Texts.TryGetValue(key, out var values)) return key;
        return args.Length == 0 ? values[languageIndex] : string.Format(Culture, values[languageIndex], args);
    }
    public static string Error(Exception ex)
    {
        if (Texts.ContainsKey(ex.Message)) return Text(ex.Message);
        var match = Texts.FirstOrDefault(x => x.Value[1] == ex.Message);
        return match.Key is not null ? Text(match.Key) : ex.Message;
    }
