        ["NtpHelp"] = ["NTP affects only this app's clocks, countdown, alerts and new history timestamps. Windows time is not changed. Brief failures keep the last synchronized clock; when it expires, Windows time is used and marked as fallback.", "NTP ovlivní pouze hodiny, odpočet, upozornění a nové časové záznamy této aplikace. Čas Windows se nemění. Krátký výpadek ponechá poslední synchronizaci; po vypršení se označeně použije čas Windows.", "NTP zmienia tylko zegary, odliczanie, alerty i nowe znaczniki czasu w aplikacji. Nie zmienia czasu Windows. Krótkie awarie zachowują synchronizację; po jej wygaśnięciu używany jest oznaczony czas Windows.", "NTP betrifft nur Uhren, Countdown, Warnungen und neue Zeitstempel dieser App. Windows-Zeit bleibt unverändert. Kurze Ausfälle nutzen die letzte Synchronisierung; danach wird Windows als Ersatz markiert.", "NTP solo afecta a relojes, cuenta atrás, alertas y nuevas marcas de tiempo de la app. No cambia Windows. Fallos breves conservan la sincronización; al caducar se indica Windows como respaldo."],
        ["NtpValidation"] = ["Enter a hostname or IP; NTP interval 2–1440 minutes and timeout 1–15 seconds.", "Zadejte název nebo IP serveru; interval NTP 2–1440 minut a timeout 1–15 sekund.", "Podaj nazwę lub IP; odstęp NTP 2–1440 minut i limit 1–15 sekund.", "Hostname oder IP eingeben; NTP-Intervall 2–1440 Minuten, Zeitlimit 1–15 Sekunden.", "Introduce nombre o IP; intervalo NTP 2–1440 minutos y límite 1–15 segundos."],
        ["ClockWindows"] = ["Time source: Windows", "Zdroj času: Windows", "Źródło czasu: Windows", "Zeitquelle: Windows", "Fuente de hora: Windows"],
        ["ClockNtp"] = ["NTP: {0} · Δ Windows {1} ms", "NTP: {0} · Δ Windows {1} ms", "NTP: {0} · Δ Windows {1} ms", "NTP: {0} · Δ Windows {1} ms", "NTP: {0} · Δ Windows {1} ms"],
        ["ClockHoldover"] = ["NTP holdover: {0} · last synchronization still valid", "NTP záloha: {0} · poslední synchronizace je stále platná", "Podtrzymanie NTP: {0} · ostatnia synchronizacja nadal ważna", "NTP-Überbrückung: {0} · letzte Synchronisierung noch gültig", "NTP retenido: {0} · última sincronización aún válida"],
        ["ClockFallback"] = ["Windows time · NTP unavailable or expired ({0})", "Čas Windows · NTP nedostupné nebo prošlé ({0})", "Czas Windows · NTP niedostępne lub wygasłe ({0})", "Windows-Zeit · NTP nicht verfügbar oder abgelaufen ({0})", "Hora Windows · NTP no disponible o caducado ({0})"],
        ["ClockSynchronizing"] = ["Synchronizing NTP: {0}…", "Synchronizuji NTP: {0}…", "Synchronizacja NTP: {0}…", "NTP-Synchronisierung: {0}…", "Sincronizando NTP: {0}…"],
        ["NtpLastSync"] = ["Last synchronization: {0} · NTP delay {1} ms", "Poslední synchronizace: {0} · NTP odezva {1} ms", "Ostatnia synchronizacja: {0} · opóźnienie NTP {1} ms", "Letzte Synchronisierung: {0} · NTP-Laufzeit {1} ms", "Última sincronización: {0} · retardo NTP {1} ms"],
        ["SyncNow"] = ["Sync now", "Synchronizovat", "Synchronizuj", "Jetzt synchronisieren", "Sincronizar"],
        ["SyncNowTip"] = ["Synchronize NTP now. At least 64 seconds between attempts; refused servers require a settings change.", "Synchronizovat NTP. Mezi pokusy nejméně 64 sekund; odmítnutý server vyžaduje změnu nastavení.", "Synchronizuj NTP. Minimum 64 sekundy między próbami; odmowa wymaga zmiany ustawień.", "NTP jetzt synchronisieren. Mindestens 64 Sekunden Abstand; verweigerte Server erfordern neue Einstellungen.", "Sincronizar NTP. Mínimo 64 segundos entre intentos; si se rechaza, cambia los ajustes."],
        ["LanguageNote"] = ["English is the default. Language and world clocks do not change the Prague restart schedule.", "Výchozí je angličtina. Jazyk ani světové hodiny nemění český plán restartů.", "Domyślnie angielski. Język i zegary nie zmieniają planu restartów w Pradze.", "Englisch ist Standard. Sprache und Weltuhren ändern den Prager Neustartplan nicht.", "Inglés por defecto. El idioma y los relojes no cambian el horario de Praga."],
        ["Theme"] = ["Whole-window theme", "Vzhled celého okna", "Motyw całego okna", "Design des gesamten Fensters", "Tema de toda la ventana"],
        ["ThemeNote"] = ["Light, dark, orange or retro grey/green. The entire window uses one palette with high-contrast player numbers.", "Jasný, tmavý, oranžový nebo retro šedozelený vzhled. Stejná paleta se použije pro pozadí, všechny karty, texty i ovládání. Čísla hráčů mají vždy vysoký kontrast.", "Jasny, ciemny, pomarańczowy lub retro szaro-zielony. Jedna paleta i czytelne liczby graczy.", "Hell, dunkel, orange oder retro grau/grün. Einheitliche Palette und kontrastreiche Spielerzahlen.", "Claro, oscuro, naranja o retro gris/verde. Una paleta y cifras de jugadores de alto contraste."],
        ["ThemeLight"] = ["Light · white / blue", "Jasný · bílá / modrá", "Jasny · biały / niebieski", "Hell · Weiß / Blau", "Claro · blanco / azul"],
        ["ThemeDark"] = ["Dark · charcoal / bright text", "Tmavý · antracit / světlý text", "Ciemny · antracyt / jasny tekst", "Dunkel · Anthrazit / heller Text", "Oscuro · antracita / texto claro"],
        ["ThemeOrange"] = ["Bold · orange / charcoal", "Výrazný · oranžová / antracit", "Wyrazisty · pomarańcz / antracyt", "Kräftig · Orange / Anthrazit", "Intenso · naranja / antracita"],
        ["ThemeSpotify"] = ["Retro · grey / green (Spotify WM)", "Retro · šedá / zelená (Spotify WM)", "Retro · szary / zielony (Spotify WM)", "Retro · Grau / Grün (Spotify WM)", "Retro · gris / verde (Spotify WM)"],
        ["Monitor"] = ["Startup monitor", "Monitor při spuštění", "Monitor przy uruchomieniu", "Startmonitor", "Monitor al iniciar"],
        ["Primary"] = ["primary", "hlavní", "główny", "primär", "principal"],
        ["MonitorNote"] = ["Window size and position are remembered. If a monitor is disconnected, the window moves to an available display.", "Polohu a velikost okna si aplikace pamatuje. Po odpojení monitoru se okno přesune na dostupnou obrazovku.", "Rozmiar i położenie są zapamiętywane. Po odłączeniu monitora okno wróci na dostępny ekran.", "Größe und Position werden gespeichert. Ohne den Monitor erscheint das Fenster auf einem verfügbaren Bildschirm.", "Se guardan tamaño y posición. Si se desconecta el monitor, la ventana pasa a otra pantalla."],
        ["AlwaysTop"] = ["Always on top", "Vždy navrchu", "Zawsze na wierzchu", "Immer im Vordergrund", "Siempre encima"],
        ["CompactOption"] = ["Compact mode (hide chart and server address)", "Kompaktní režim (skrýt graf a adresu serveru)", "Tryb kompaktowy (ukryj wykres i adres)", "Kompaktmodus (Diagramm und Adresse ausblenden)", "Modo compacto (ocultar gráfico y dirección)"],
        ["Clock24"] = ["24-hour clock", "24hodinový formát času", "Format 24-godzinny", "24-Stunden-Format", "Formato de 24 horas"],
        ["OffsetClockOption"] = ["Also show the calculated offset clock", "Zobrazit také vypočtený serverový čas", "Pokaż też obliczony zegar z przesunięciem", "Zusätzliche Uhr mit berechnetem Versatz", "Mostrar también reloj con desfase calculado"],
        ["Offset"] = ["Offset from Prague time (hours)", "Posun serverového času vůči českému času (hodiny)", "Przesunięcie od czasu Pragi (godziny)", "Versatz zur Prager Zeit (Stunden)", "Desfase respecto a Praga (horas)"],
        ["OffsetHelp"] = ["Default −1 h is a configurable assumption, not the DayZ game clock. The countdown always uses Prague time.", "Výchozí −1 h je předpoklad, který lze změnit. Jde o přičtený offset, nikoli čas přečtený z DayZ serveru. Odpočet používá český čas nezávisle na tomto nastavení.", "Domyślne −1 h to założenie, nie czas gry DayZ. Odliczanie zawsze używa czasu Pragi.", "−1 h ist eine änderbare Annahme, keine DayZ-Spielzeit. Der Countdown nutzt immer Prager Zeit.", "−1 h es una suposición configurable, no la hora del juego. La cuenta atrás usa la hora de Praga."],
        ["FullscreenHelp"] = ["F11 toggles full screen. Escape returns to the window.", "F11 přepne celou obrazovku. Escape se vrátí do okna.", "F11 przełącza pełny ekran. Escape wraca do okna.", "F11 schaltet Vollbild um. Escape kehrt zum Fenster zurück.", "F11 alterna pantalla completa. Escape vuelve a la ventana."],
        ["VisualAlerts"] = ["Colour alerts before and during restart", "Barevná upozornění před restartem a při restartu", "Kolorowe alerty przed restartem i podczas niego", "Farbwarnungen vor und beim Neustart", "Alertas de color antes y durante el reinicio"],
        ["SoundAlerts"] = ["Sound alerts", "Zvukové upozornění", "Alerty dźwiękowe", "Akustische Warnungen", "Alertas sonoras"],
        ["Notifications"] = ["Windows notification-area alerts", "Windows oznámení z oznamovací oblasti", "Alerty z obszaru powiadomień Windows", "Windows-Infobereich-Benachrichtigungen", "Alertas del área de notificaciones de Windows"],
        ["NotificationNote"] = ["Do Not Disturb may suppress alerts. They follow your schedule, not a proven kick or restart. Each level is delivered once per scheduled restart, with a record on disk.", "Windows může oznámení potlačit režimem Nerušit. Upozornění vycházejí z plánu a neověřují skutečný kick nebo restart. Každá úroveň se doručí nejvýše jednou na plánovaný restart; záznam je uložen na disku.", "Nie przeszkadzać może blokować alerty. Wynikają z planu, nie dowodzą restartu. Każdy poziom jest zapisany i dostarczany raz.", "Nicht stören kann Warnungen unterdrücken. Sie folgen dem Plan, belegen keinen Neustart. Jede Stufe wird einmal gesendet und gespeichert.", "No molestar puede ocultar alertas. Siguen el horario, no prueban reinicios. Cada nivel se entrega una vez y se registra."],
        ["Startup"] = ["Start automatically when signing in to Windows", "Automaticky spustit po přihlášení do Windows", "Uruchom przy logowaniu do Windows", "Bei Windows-Anmeldung automatisch starten", "Iniciar al entrar en Windows"],
        ["StartupNote"] = ["Current user only. After moving the EXE, disable and re-enable this option.", "Pouze pro aktuálního uživatele. Při přesunutí EXE tuto volbu vypněte a znovu zapněte.", "Tylko bieżący użytkownik. Po przeniesieniu EXE wyłącz i włącz ponownie.", "Nur aktueller Benutzer. Nach Verschieben der EXE aus- und wieder einschalten.", "Solo usuario actual. Tras mover el EXE, desactiva y activa esta opción."],
        ["Retention"] = ["History retention (days)", "Uchování historie (dny)", "Przechowywanie historii (dni)", "Verlauf aufbewahren (Tage)", "Conservar historial (días)"],
        ["HistoryHelp"] = ["Queries are stored locally as JSONL: UTC time, status, players, capacity, RTT, failures and query recovery. Limit 16 MB/day. Old daily files are removed automatically.", "Každý dotaz se ukládá lokálně jako JSONL: čas UTC, stav, hráči, kapacita, RTT, chyba a zachycené obnovení query. Denní limit 16 MB. Starší denní soubory se automaticky odstraňují.", "Zapytania są zapisywane lokalnie jako JSONL: UTC, stan, gracze, pojemność, RTT, błędy i powrót query. Limit 16 MB/dzień. Stare pliki usuwane automatycznie.", "Abfragen lokal als JSONL: UTC, Status, Spieler, Kapazität, RTT, Fehler und Query-Rückkehr. Limit 16 MB/Tag. Alte Dateien werden automatisch entfernt.", "Consultas locales en JSONL: UTC, estado, jugadores, capacidad, RTT, fallos y recuperación. Límite 16 MB/día. Se eliminan archivos antiguos."],
        ["OpenData"] = ["Open data folder", "Otevřít složku s daty", "Otwórz folder danych", "Datenordner öffnen", "Abrir carpeta de datos"],
        ["Cancel"] = ["Cancel", "Zrušit", "Anuluj", "Abbrechen", "Cancelar"],
        ["SaveSettings"] = ["Save settings", "Uložit nastavení", "Zapisz ustawienia", "Einstellungen speichern", "Guardar ajustes"],
        ["WorldIntro"] = ["Add up to 8 clocks. Each uses its own time zone and daylight-saving rules. City and country labels are editable. Restart times stay in Prague time.", "Přidejte až 8 hodin. Každé mají vlastní pásmo a letní čas. Město i zkratku země lze změnit. Restarty zůstávají v českém čase.", "Dodaj do 8 zegarów z własną strefą i zmianą czasu. Nazwy miast i krajów można zmieniać. Restarty zostają w czasie Pragi.", "Bis zu 8 Uhren mit eigener Zeitzone und Sommerzeit. Stadt und Länderkürzel frei wählbar. Neustarts bleiben in Prager Zeit.", "Añade hasta 8 relojes con zona y horario de verano propios. Ciudad y país editables. Reinicios siempre en hora de Praga."],
        ["Preset"] = ["City preset", "Předvolba města", "Gotowe miasto", "Stadtvorlage", "Ciudad predefinida"],
