        ["ClockEnabled"] = ["Show this clock", "Zobrazit tyto hodiny", "Pokaż ten zegar", "Diese Uhr anzeigen", "Mostrar este reloj"],
        ["AddClock"] = ["Add clock", "Přidat hodiny", "Dodaj zegar", "Uhr hinzufügen", "Añadir reloj"],
