        ["RestartNotice"] = ["Restart in {0} min", "Restart za {0} min", "Restart za {0} min", "Neustart in {0} Min.", "Reinicio en {0} min"],
        ["RestartNow"] = ["Expected restart", "Očekávaný restart", "Oczekiwany restart", "Neustart erwartet", "Reinicio previsto"],
        ["UnconfirmedSuffix"] = [" · unconfirmed schedule", " · nepotvrzený plán", " · niepotwierdzony plan", " · unbestätigter Zeitplan", " · horario sin confirmar"],
        ["RecoveredTitle"] = ["Query service responding again", "Query služba opět odpovídá", "Usługa query znów odpowiada", "Query-Dienst antwortet wieder", "El servicio de consultas vuelve a responder"],
        ["RecoveredBody"] = ["Query recovery observed at {0}.", "Obnovení query zjištěno v {0}.", "Powrót query wykryto o {0}.", "Query-Rückkehr um {0} erkannt.", "Recuperación de consultas detectada a las {0}."],
        ["SaveError"] = ["Unable to save settings: {0}", "Nastavení nelze uložit: {0}", "Nie można zapisać ustawień: {0}", "Einstellungen nicht gespeichert: {0}", "No se pueden guardar ajustes: {0}"],
        ["HistoryError"] = ["Unable to save history: {0}", "Historii nelze uložit: {0}", "Nie można zapisać historii: {0}", "Verlauf nicht gespeichert: {0}", "No se puede guardar el historial: {0}"],
        ["LedgerError"] = ["Unable to save alert record: {0}", "Záznam upozornění nelze uložit: {0}", "Nie można zapisać alertów: {0}", "Warnungsprotokoll nicht gespeichert: {0}", "No se puede guardar el registro de alertas: {0}"],
        ["LedgerReadError"] = ["Unable to read alert record: {0}", "Nelze načíst záznam upozornění: {0}", "Nie można odczytać alertów: {0}", "Warnungsprotokoll nicht lesbar: {0}", "No se puede leer el registro de alertas: {0}"],
        ["ServerChangeError"] = ["Unable to change server: {0}", "Server nelze změnit: {0}", "Nie można zmienić serwera: {0}", "Serverwechsel nicht möglich: {0}", "No se puede cambiar el servidor: {0}"],
        ["IntegerError"] = ["{0}: enter a whole number.", "{0}: zadejte celé číslo.", "{0}: wpisz liczbę całkowitą.", "{0}: ganze Zahl eingeben.", "{0}: introduce un número entero."],
        ["OffsetError"] = ["Enter a numeric offset, for example -1 or 0.", "Posun času: zadejte číslo, například −1 nebo 0.", "Wpisz przesunięcie, np. -1 lub 0.", "Numerischen Versatz eingeben, z. B. -1 oder 0.", "Introduce un desfase numérico, por ejemplo -1 o 0."],
        ["ServerStored"] = ["Server added to the list. Confirm with Save settings.", "Server je v seznamu. Změny potvrďte tlačítkem Uložit nastavení.", "Serwer na liście. Potwierdź przyciskiem Zapisz ustawienia.", "Server in Liste. Mit Einstellungen speichern bestätigen.", "Servidor en la lista. Confirma con Guardar ajustes."],
        ["ServerLimit"] = ["Up to 50 saved servers are allowed.", "Seznam může obsahovat nejvýše 50 serverů.", "Można zapisać do 50 serwerów.", "Bis zu 50 gespeicherte Server möglich.", "Se permiten hasta 50 servidores guardados."],
        ["LanguageInvalid"] = ["Choose EN, CZ, PL, DE or ES.", "Vyberte EN, CZ, PL, DE nebo ES.", "Wybierz EN, CZ, PL, DE lub ES.", "EN, CZ, PL, DE oder ES wählen.", "Elige EN, CZ, PL, DE o ES."],
        ["WorldClocksLimit"] = ["Up to 8 world clocks are allowed.", "Lze zadat nejvýše 8 světových hodin.", "Można dodać do 8 zegarów.", "Bis zu 8 Weltuhren möglich.", "Se permiten hasta 8 relojes mundiales."],
        ["WorldClockInvalid"] = ["Enter a city (1–40 characters), country code (up to 8) and time zone.", "Zadejte město (1–40 znaků), zkratku země (nejvýše 8) a pásmo.", "Podaj miasto (1–40 znaków), kod kraju (do 8) i strefę.", "Stadt (1–40 Zeichen), Länderkürzel (bis 8) und Zeitzone eingeben.", "Introduce ciudad (1–40 caracteres), código de país (hasta 8) y zona."],
        ["WorldClockZoneInvalid"] = ["The time zone is not available on this computer.", "Časové pásmo není v tomto počítači dostupné.", "Strefa czasowa jest niedostępna na tym komputerze.", "Die Zeitzone ist auf diesem Computer nicht verfügbar.", "La zona horaria no está disponible en este equipo."],
        ["SelectClock"] = ["Select a clock to edit.", "Vyberte hodiny k úpravě.", "Wybierz zegar do edycji.", "Eine Uhr zum Ändern auswählen.", "Selecciona un reloj para editarlo."],
        ["NotificationError"] = ["Cannot display notification: {0}", "Oznámení nelze zobrazit: {0}", "Nie można pokazać powiadomienia: {0}", "Benachrichtigung nicht möglich: {0}", "No se puede mostrar la notificación: {0}"],
        ["NotificationAreaError"] = ["Notification area unavailable: {0}", "Oznamovací oblast není dostupná: {0}", "Obszar powiadomień niedostępny: {0}", "Infobereich nicht verfügbar: {0}", "Área de notificaciones no disponible: {0}"],
        ["ExePathError"] = ["Cannot determine the application path.", "Nelze určit cestu aplikace.", "Nie można ustalić ścieżki aplikacji.", "Anwendungspfad nicht ermittelbar.", "No se puede determinar la ruta de la aplicación."],
        ["ProfileScheduleError"] = ["A saved server profile has no restart schedule.", "Profil serveru nemá restartovací plán.", "Zapisany profil nie ma planu restartów.", "Ein Serverprofil hat keinen Neustartplan.", "Un perfil guardado no tiene horario de reinicios."],
        ["EmptyJsonError"] = ["Empty JSON document.", "Prázdný JSON dokument.", "Pusty dokument JSON.", "Leeres JSON-Dokument.", "Documento JSON vacío."],
        ["InvalidAnchor"] = ["Use HH:mm for the anchor time.", "Výchozí čas zadejte jako HH:mm.", "Użyj HH:mm dla czasu bazowego.", "Startzeit als HH:mm eingeben.", "Usa HH:mm para la hora de referencia."],
        ["AlreadyRunning"] = ["A monitor already uses this data folder.", "Monitor pro tuto datovou složku už běží.", "Monitor już używa tego folderu danych.", "Ein Monitor verwendet diesen Datenordner bereits.", "Un monitor ya utiliza esta carpeta de datos."],
        ["ConfigError"] = ["Cannot load or save configuration:\n{0}\n\n{1}\n\nFix the JSON or move the app to a writable folder. The original file was not replaced.", "Nelze načíst nebo uložit konfiguraci:\n{0}\n\n{1}\n\nOpravte JSON nebo přesuňte aplikaci do zapisovatelné složky. Původní soubor nebyl přepsán.", "Nie można odczytać lub zapisać konfiguracji:\n{0}\n\n{1}\n\nPopraw JSON lub przenieś aplikację do zapisywalnego folderu. Pliku nie zastąpiono.", "Konfiguration nicht lesbar oder speicherbar:\n{0}\n\n{1}\n\nJSON korrigieren oder beschreibbaren Ordner nutzen. Original nicht ersetzt.", "No se puede leer o guardar configuración:\n{0}\n\n{1}\n\nCorrige JSON o usa una carpeta con escritura. No se sustituyó el original."],
        ["ValidationName"] = ["Server name must contain 1–180 characters.", "Název serveru musí mít 1–180 znaků.", "Nazwa serwera: 1–180 znaków.", "Servername: 1–180 Zeichen.", "Nombre del servidor: 1–180 caracteres."],
        ["ValidationIp"] = ["Enter a valid server IP address.", "Zadejte platnou IP adresu serveru.", "Podaj prawidłowy adres IP serwera.", "Gültige Server-IP eingeben.", "Introduce una IP válida del servidor."],
        ["ValidationIpSpecific"] = ["Enter a specific server IP address.", "Zadejte konkrétní IP adresu serveru.", "Podaj konkretny adres IP serwera.", "Konkrete Server-IP eingeben.", "Introduce una IP concreta del servidor."],
        ["ValidationPorts"] = ["Ports must be between 1 and 65535.", "Porty musí být v rozsahu 1–65535.", "Porty muszą być w zakresie 1–65535.", "Ports müssen zwischen 1 und 65535 liegen.", "Los puertos deben estar entre 1 y 65535."],
        ["ValidationSchedule"] = ["Use 1–48 distinct times in HH:mm format.", "Plán musí obsahovat 1–48 různých časů ve formátu HH:mm.", "Podaj 1–48 różnych godzin HH:mm.", "1–48 unterschiedliche HH:mm-Zeiten verwenden.", "Usa 1–48 horas distintas en formato HH:mm."],
